export function isUpwardSwipe(dx,dy,elapsed){return Number.isFinite(dx)&&Number.isFinite(dy)&&Number.isFinite(elapsed)&&elapsed>=0&&elapsed<=1400&&dy<=-56&&Math.abs(dx)<=Math.max(30,Math.abs(dy)*.55)}
export function bindQiblaSwipe(surface,onOpen){if(!surface)return;let gesture=null,blockClick=false;surface.addEventListener('pointerdown',event=>{gesture=null;blockClick=false;if(!event.isPrimary||event.button!==0){gesture=null;blockClick=true;return}if(event.target?.closest('a,input,select,textarea,[data-no-swipe]'))return;gesture={x:event.clientX,y:event.clientY,id:event.pointerId,time:event.timeStamp};try{surface.setPointerCapture?.(event.pointerId)}catch{}});surface.addEventListener('pointercancel',()=>{gesture=null;blockClick=true});surface.addEventListener('pointerup',event=>{const start=gesture;gesture=null;if(!start||start.id!==event.pointerId)return;const dx=event.clientX-start.x,dy=event.clientY-start.y;blockClick=Math.hypot(dx,dy)>10;if(!surface.ownerDocument?.defaultView?.getSelection?.()?.toString()&&isUpwardSwipe(dx,dy,event.timeStamp-start.time))onOpen()});surface.addEventListener('click',event=>{if(!blockClick)return;event.preventDefault();event.stopImmediatePropagation();blockClick=false},true);surface.addEventListener('keydown',event=>{if(event.target===surface&&event.key==='ArrowUp'){event.preventDefault();onOpen()}})}
